value.en:
int counter = 0;
print("Counting with while:");
while counter < 3: {
    print("  Number " + counter);
    counter = counter + 1;
}

// Single-statement mode
counter = 0;
while counter < 2: counter = counter + 1;
print("End: " + counter);

